    <label style={{ display: "block", padding: 8, fontFamily: "sans-serif", fontSize: 14 }}>
      {label}
      <input style={{ display: "block", padding: 8, fontFamily: "sans-serif", fontSize: 14 }} value={value} onChange={(e) => onChange(e.target.value)} />
    </label>
  );
}

